import 'package:flutter/material.dart';
import '../services/api_service.dart';

class ManifestScreen extends StatefulWidget{final ApiService api;final String? submenu;const ManifestScreen({super.key,required this.api,this.submenu});@override State<ManifestScreen> createState()=>_ManifestScreenState();}
class _ManifestScreenState extends State<ManifestScreen>{List<dynamic> rows=[];bool loading=true;@override void initState(){super.initState();load();}Future<void> load()async{setState(()=>loading=true);try{final d=await widget.api.get('/manifests');rows=d is Map&&d['manifests'] is List?d['manifests']:d is List?d:[];}catch(e){_msg(e.toString());}finally{if(mounted)setState(()=>loading=false);}}void _msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));Future<void> generate()async{try{await widget.api.post('/manifests/generate',{});_msg('Manifest berhasil dibuat');load();}catch(e){_msg(e.toString());}}Future<void> reconcile(String id)async{try{await widget.api.put('/manifests/$id/reconcile',{'status':'reconciled'});_msg('Manifest direkonsiliasi');load();}catch(e){_msg(e.toString());}}
@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[Text(widget.submenu??'Manifest',style:const TextStyle(fontSize:22,fontWeight:FontWeight.w900)),const SizedBox(height:5),Text(_desc(),style:const TextStyle(color:Colors.grey)),const SizedBox(height:16),if(widget.submenu==null||widget.submenu=='Grouping Armada')SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:generate,icon:const Icon(Icons.add),label:const Text('Generate Manifest'))),if(loading)const LinearProgressIndicator(),const SizedBox(height:10),...rows.map((r){final m=r is Map?r:<String,dynamic>{};final id=m['_id']??m['id'];return Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${m['name']??m['manifestCode']??'Manifest'}',style:const TextStyle(fontSize:16,fontWeight:FontWeight.w800)),const SizedBox(height:5),Text('Driver: ${m['driverName']??'-'} • Nopol: ${m['nopol']??'-'}',style:const TextStyle(color:Colors.grey)),const SizedBox(height:8),Text('Berat: ${m['totalWeight']??0} kg • Pallet: ${m['pallets'] is List?m['pallets'].length:m['palletCount']??0}'),if(widget.submenu=='Rekonsiliasi'||widget.submenu==null)...[const SizedBox(height:8),OutlinedButton(onPressed:id==null?null:()=>reconcile('$id'),child:const Text('Rekonsiliasi'))]])));})]);
String _desc(){switch(widget.submenu){case 'Rekonsiliasi':return'Periksa dan tandai manifest yang sudah direkonsiliasi.';case 'Master Summary & Weight':return'Ringkasan berat dan jumlah pallet.';case 'Breakdown Kemasan':return'Pantau breakdown karton, karung, dan box.';case 'Cetak & Export':return'Data manifest siap digunakan oleh web untuk cetak/export.';default:return'Operasional manifest di lapangan.';}}
}
